Script.Data:
/* If BOPStructure.BuildingLimit page field = "0", populate the BOPStructure.BuildingLimitRange page field with the range value of "0".  If BOPStructure.BuildingLimit page field > "0", then populate the BOPStructure.BuildingLimitRange page field with the range value of "1 through 999999999" on the Structure page.  */


PopRange1To999999999(document.form1.XPath_BuildingLimit,document.form1.XPath_BuildingLimitRange);

var func = document.form1.XPath_BuildingLimitRange.onchange;
eval(func + "anonymous();");

/* 
If BOPClassification.BusnPrsnlPropLimit page field = "0", 
  populate the BOPClassification.BusnPrsnlPropLimitRange page field with the range value of "0". 

If BOPClassification.BusnPrsnlPropLimit page field > "0", 
  then populate the BOPClassification.BusnPrsnlPropLimitRange page field with the range value of "1 through 999999999" on the Classification page
*/ 

PopRange1To999999999(document.form1.XPath_BusnPrsnlPropLimit,document.form1.XPath_BusnPrsnlPropLimitRange);

SetClassOptLimitsISOBOPCW(document.form1.XPath_BusnPrsnlPropLimit, 'onBlur', 'XPath_BusnPrsnlPropLimit');

var func = document.form1.XPath_BusnPrsnlPropLimitRange.onchange;
eval(func + "anonymous();");

if ( typeof(document.form1.XPath_EFTAccountNumber) == 'undefined')
  {
    alert('ConfirmRoutingNumberISOCACW : Account Number is undefined');
    return;
  }
  if ( typeof(document.form1.XPath_ConfirmAccountNumber) == 'undefined')
  {
    alert('ConfirmRoutingNumberISOCACW : Confirm Account Number is undefined');
    return;
  }

  var Account = document.form1.XPath_EFTAccountNumber;
  var ConfirmAccount = document.form1.XPath_ConfirmAccountNumber;


  if (Account.value == "")
  {
	ConfirmAccount.value = ""; 
	return; 
  }	
  else
  {
	var reMatch = /^\d{1,32}$/;

	if (!reMatch.test(Account.value)) 
	{
  	  alert("Account Number must be numeric");
	  Account.value = "";
	  Account.focus();
	  return;
	}   
	if ((!reMatch.test(ConfirmAccount.value)) && (ConfirmAccount.value != "")) 
	{
  	  alert("Confirm Account Number must be numeric");
	  ConfirmAccount.value = "";
	  ConfirmAccount.focus();
	  return;
	}
	if ((Account.value != ConfirmAccount.value) && (ConfirmAccount.value != ""))
	{
	  alert("Confirm Account Number does not match Account Number, \nplease re-enter Confirm Account Number");
	  ConfirmAccount.value = "";
	  ConfirmAccount.focus();
	  return;
	}
  }

if ( typeof(document.form1.XPath_EFTBankRoutingNumber) == 'undefined')
  {
    alert('ConfirmRoutingNumberISOCACW : Routing Number is undefined');
    return;
  }
  if ( typeof(document.form1.XPath_ConfirmBankRoutingNumber) == 'undefined')
  {
    alert('ConfirmRoutingNumberISOCACW : Confirm Routing Number is undefined');
    return;
  }

  Routing = document.form1.XPath_EFTBankRoutingNumber;
  ConfirmRouting = document.form1.XPath_ConfirmBankRoutingNumber;

  if (Routing.value == "")
  {
    ConfirmRouting.value = "";
    return;
  }  
  else
  {
	var reMatch = /\d{9}/;

	if (!reMatch.test(Routing.value)) 
	{
  	  alert("Routing Number must be a 9 digit number");
	  Routing.value = "";
	  Routing.focus();
	  return;
	}   
	if ((!reMatch.test(ConfirmRouting.value)) && (ConfirmRouting.value != "")) 
	{
  	  alert("Confirm Routing Number must be a 9 digit number");
	  ConfirmRouting.value = "";
	  ConfirmRouting.focus();
	  return;		
	}
	if ((Routing.value != ConfirmRouting.value) && (ConfirmRouting.value != ""))
	{
	  alert("Confirm Routing Number does not match Routing Number, \nplease re-enter Confirm Routing Number");
	  ConfirmRouting.value = "";
	  ConfirmRouting.focus();
	  return;
	}
  }

if ( typeof(document.form1.XPath_EFTAccountNumber) == 'undefined' )
  {
    alert('DisableConfirmAccountNumberISOCACW : Account Number is undefined');
    return;
  }
  if ( typeof(document.form1.XPath_ConfirmAccountNumber) == 'undefined' )
  {
    alert('DisableConfirmAccountNumberISOCACW : Confirm Account Number is undefined');
    return;
  }

  AccountNumber = document.form1.XPath_EFTAccountNumber;
  Confirm = document.form1.XPath_ConfirmAccountNumber;

  DisableFieldFocus(AccountNumber,Confirm,"");

if ( typeof(document.form1.XPath_EFTBankRoutingNumber) == 'undefined' )
  {
    alert('DisableConfirmRoutingNumberISOCACW : Routing Number is undefined');
    return;
  }
  if ( typeof(document.form1.XPath_ConfirmBankRoutingNumber) == 'undefined' )
  {
    alert('DisableConfirmRoutingNumberISOCACW : Confirm Routing Number is undefined');
    return;
  }

  RoutingNumber = document.form1.XPath_EFTBankRoutingNumber;
  Confirm = document.form1.XPath_ConfirmBankRoutingNumber;

  DisableFieldFocus(RoutingNumber,Confirm,"");

if ((typeof(document.form1.XPath_PaymentPlan) != 'undefined') &&
    (typeof(document.form1.XPath_DownPaymentAmount) != 'undefined'))
{

  if (typeof(document.form1.XPath_FollowOnPaymentType) != 'undefined')
  {
    var InstType = document.form1.XPath_FollowOnPaymentType;	      
    if (InstType.value == 'EFT') 
      var FeeAmt = 0;
    else
      var FeeAmt = 5;
  }		
  var PayPlan = document.form1.XPath_PaymentPlan;

  switch(PayPlan.value)
  {
	case 'Two Pay':
		var Percent = .50;
		var Dep = .50;
		break;
	case '4 Pay':
		var Percent = .20;
		var Dep = .40;
		break;
	case 'Monthly':
		var Percent = .083;
		var Dep = .083;
		break;			
  }

CalculatePayments(Dep,Percent,FeeAmt);
}

var strManagementPct = new String(document.form1.XPath_ManagementPct.value);
	var strLocationPct = new String(document.form1.XPath_LocationPct.value);
	var strBuildingFeaturesPct = new String(document.form1.XPath_BuildingFeaturesPct.value);
	var strPremisesEquipmentPct = new String(document.form1.XPath_PremisesEquipmentPct.value);
	var strEmployeesPct = new String(document.form1.XPath_EmployeesPct.value);
	var strProtectionPct = new String(document.form1.XPath_ProtectionPct.value);
	var PctTotal;

        //Remove percent symbol from string values
	strManagementPct = StripPCT(strManagementPct);
	strLocationPct = StripPCT(strLocationPct);
	strBuildingFeaturesPct = StripPCT(strBuildingFeaturesPct);
	strPremisesEquipmentPct = StripPCT(strPremisesEquipmentPct);
	strEmployeesPct = StripPCT(strEmployeesPct);
	strProtectionPct = StripPCT(strProtectionPct);

        //Add the numbers together
	PctTotal = AddSixNumbers(strManagementPct, strLocationPct, strBuildingFeaturesPct, strPremisesEquipmentPct, strEmployeesPct, strProtectionPct);

        //Total must fall within -25 to 25 range
	var nPctTotal = PctTotal - 0;

	if (((nPctTotal > 25) || (nPctTotal < -25)) && (!(bAlerted)))
	{
                //bAlerted controls the display of the message.
                //This flag will toggle as the message so that it is
                //displayed only once
		bAlerted = true;
		alert("The total credit/debit cannot exceed 25%");

	}
	else if((nPctTotal < 25) && (nPctTotal > -25))
	{
		bAlerted = false;
	}

	document.form1.XPath_TotalModificationPct.value = PctTotal;

/*If BOPProtectiveSafeguards.ProtectiveDeviceOrService <> "P-9" Other clear and disable BOPProtectiveSafeguards.P9Desc
*/


var ProtectiveDevice = document.form1.AORuntimeSelect_XPath_ProtectiveDeviceOrService;
var P9 = document.form1.XPath_P9Desc;

if (fld.name == "XPath_P9Desc" || fld.name == "XPath_ProtectiveDeviceOrService")
{
  if (fld.name == "XPath_ProtectiveDeviceOrService" && ProtectiveDevice.value != 'P-9 Other')
  {
    P9.value = "";
  }
  if (fld.name == "XPath_P9Desc" && ProtectiveDevice.value != 'P-9 Other')
  {
    P9.value = "";
    ProtectiveDevice.focus();
  }
}

/* 
If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctlBusnPrsnlPropValtnApply = "No", then set BOPClassificationAccountsReceivableCoverage.Limit AND BOPClassificationValuablePapersCoverage.Limit to "0".  If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctlBusnPrsnlPropValtnApply = "Yes" AND BOPClassificationAccountsReceivableCoverage.Limit < "10000", then set field to "10000".  If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctlBusnPrsnlPropValtnApply = "Yes" AND BOPClassificationValuablePapersCoverage.Limit < "10000", then set field to "10000".  If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctlBusnPrsnlPropValtnApply = "Yes" AND BOPClassificationAccountsReceivableCoverage.Limit >= "10000", do not change field value. If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctlBusnPrsnlPropValtnApply = "Yes" AND BOPClassificationValuablePapersCoverage.Limit >= "10000", do not change field value. If BOPClassification.BusnPrsnlPropLimit > "0" AND BOPClassificationAccountsReceivableCoverage.Limit < "10000", then set field to "10000".  If BOPClassification.BusnPrsnlPropLimit > "0" AND BOPClassificationValuablePapersCoverage.Limit < "10000", then set field to "10000".  If BOPClassification.BusnPrsnlPropLimit > "0" AND BOPClassificationAccountsReceivableCoverage.Limit >= "10000", do not change field value. If BOPClassification.BusPrsnlPropLimit > "0" AND BOPClassificationValuablePapersCoverage.Limit >= "10000", do not change field value. 

If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctlBusnPrsnlPropValtnApply = "Yes" AND BOPClassificationBusnIncomeDependentPropCoverage.Limit < "5000", 
then set field to "5000".  

If BOPClassification.BusnPrsnlPropLimit = "0" AND BOPClassification.FunctBusPersPropValtnApply = "Yes" AND BOPClassificationBusnIncomeDependentPropCoverage.Limit >= "5000", 
do not change field value. 

If BOPClassification.BusnPrsnlPropLimit > "0" AND BOPClassificationBusnIncomeDependentPropCoverage.Limit < "5000", 
then set field to "5000".  

If BOPClassification.BusnPrsnlPropLimit > "0" AND BOPClassificationBusnIncomeDependentPropCoverage.Limit >= "5000", do not change field value.

*/

var BusnPrsnlPropLimit = document.form1.XPath_BusnPrsnlPropLimit;
var FunctBusPersPropValApply = document.form1.XPath_FunctlBusnPrsnlPropValtnApply;
var ARCoverageLimit = document.form1.XPath_BOPClassificationAccountsReceivableCoverage_Limit;
var ValPapersCoverageLimit = document.form1.XPath_BOPClassificationValuablePapersCoverage_Limit;
var DepPropCoverageLimit = document.form1.XPath_BOPClassificationBusnIncomeDependentPropCoverage_Limit;

if (BusnPrsnlPropLimit.value <= 0)
{
  if (FunctBusPersPropValApply.value == "Yes")
  {
    if (ARCoverageLimit.value < 10000)
      ARCoverageLimit.value = 10000;
    if (ValPapersCoverageLimit.value < 10000)
      ValPapersCoverageLimit.value = 10000;
    if (DepPropCoverageLimit.value < 5000)
      DepPropCoverageLimit.value = 5000;
  }
  else if (FunctBusPersPropValApply.value == "No")
  {
    ARCoverageLimit.value = 0;
    ValPapersCoverageLimit.value = 0;
    DepPropCoverageLimit.value = 0;
  }
}
else if (BusnPrsnlPropLimit.value > 0)
{
  if (ARCoverageLimit.value < 10000)
      ARCoverageLimit.value = 10000;
  if (ValPapersCoverageLimit.value < 10000)
      ValPapersCoverageLimit.value = 10000;
  if (DepPropCoverageLimit.value < 5000)
      DepPropCoverageLimit.value = 5000;
}
else
  return;

if ((typeof(document.form1.XPath_DownPaymentAmount)!='undefined') ||
    (typeof(document.form1.XPath_DownPaymentAmountValidation)!='undefined')) 
{ 
  var Fld = document.form1.XPath_DownPaymentAmount; 
  var hFld = document.form1.XPath_DownPaymentAmountValidation; 
  hFld.value = Fld.value; 
}

/* If BOPOrdinanceOrLawCov.Coverage = "Coverage 1 Only", "Coverage 3 Only", "Coverages 1 and 2" OR "Coverages 1, 2 and 3", then set BOPOrdinanceOrLawCov3Coverage.Limit = "10000" if BOPOrdinanceOrLawCov3Coverage.Limit < "10000".  If BOPOrdinanceOrLawCov.Coverage = "Coverage 1 with Coverages 2 and 3 Combined", then set BOPOrdinanceOrLawCov2And3Coverage.Limit = "10000" if BOPOrdinanceOrLawCov2And3Coverage.Limit < "10000"  If BOPOrdinanceOrLawCov.Coverage <> "Coverages 1 and 2" OR "Coverages 1, 2 and 3", then set BOPOrdinanceOrLawCov2Coverage.Limit = "0". */

var Coverage = document.form1.XPath_Coverage;
var Cov2Limit = document.form1.XPath_BOPOrdinanceOrLawCov2Coverage_Limit;
var Cov3Limit = document.form1.XPath_BOPOrdinanceOrLawCov3Coverage_Limit;
var Cov2And3Limit = document.form1.XPath_BOPOrdinanceOrLawCov2And3Coverage_Limit;

switch(Coverage.value)
{
  case "Coverage 1 Only":
    Cov2Limit.value = 0;
    Cov3Limit.value = 10000;
    Cov2And3Limit.value = 0;
    break;
  case "Coverage 3 Only":
    Cov2Limit.value = 0;
    Cov2And3Limit.value = 0;
    if (Cov3Limit.value < 10000)
      Cov3Limit.value = 10000;
    break;
  case "Coverages 1 and 2":
  //Cov2Limit.value = ??;
    Cov3Limit.value = 10000;
    Cov2And3Limit.value = 0;
    break;
  case "Coverages 1, 2 and 3":
  //Cov2Limit.value = ??;
    Cov2And3Limit.value = 0;
    if (Cov3Limit.value < 10000)
      Cov3Limit.value = 10000;
    break;
  case "Coverage 1 with Coverages 2 and 3 Combined":
    Cov2Limit.value = 0;
    Cov3Limit.value = 0;
    if (Cov2And3Limit.value < 10000)
      Cov2And3Limit.value = 10000;
    break;
  default:
    Cov2Limit.value = 0;
    Cov3Limit.value = 0;
    Cov2And3Limit.value = 0;
}

var BPP = document.form1.XPath_BusnPrsnlPropLimit;
var BPPVal = document.form1.XPath_FunctlBusnPrsnlPropValtnApply;
var AR = document.form1.XPath_BOPClassificationAccountsReceivableCoverage_Limit;

if (((BPP.value-0) > 0) ||
    (((BPP.value-0) == 0) && (BPPVal == 'Yes')))
{
  if (AR.value < 10000)
  {
    alert("Accounts Receivable On-Premises Limit must be at least 10000");
    AR.value = 10000;
  }
}

if (((BPP.value-0) == 0) && (BPPVal == 'No'))
{
  alert("Accounts Receivable On-Premises Limit must be 0");
  AR.value = 0;
}
